{
  "references": [
    {
      "id": "R1",
      "summary_ko": "코를 포함한 남성의 얼굴이 알아볼 수 없을 정도로 흐려짐."
    },
    {
      "id": "R2",
      "summary_ko": "사용되는 아이스 액스가 때때로 곧지 않고 휘어짐."
    },
    {
      "id": "R3",
      "summary_ko": "프롬프트와 달리 등반하는 사람이 아이스 액스를 사용하지 않음."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "등반 스틱/아이스 액스 자루가 단단한 형태를 유지하지 못하고 부자연스럽게 휘어지고 늘어남."
    },
    {
      "id": "C2",
      "summary_ko": "등반가의 왼손에 든 스틱/아이스 액스가 휘어지고 변형되며 눈 표면과 부자연스럽게 분리되거나 합쳐짐."
    },
    {
      "id": "C3",
      "summary_ko": "등반가의 다리와 부츠 비율이 일정하지 않게 변하고 눈 표면을 뚫고 들어가는 오류가 발생함."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 얼굴의 블러 현상에 관한 것이고, C1은 아이스 액스의 휘어짐 및 변형에 관한 것으로 대상과 결함이 완전히 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 얼굴 블러링을 다루고, C2는 아이스 액스의 변형 및 눈과의 병합을 다루므로 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R1은 얼굴 블러 현상이며, C3은 다리와 부츠의 비율 변화 및 관통 오류로 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "same",
      "reason_ko": "R2와 C1 모두 사용 중인 아이스 액스가 직선을 유지하지 못하고 비정상적으로 휘어지거나 굽어지는 동일한 결함을 설명합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "C2도 아이스 액스가 휘어지는 현상을 언급하지만 왼손 물체의 특정 변형 및 눈 표면과의 결합/분리 오류를 함께 포함하여 R2와 완전히 동일한 현상인지 판단하기 모호합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R2는 아이스 액스의 형태 이상을 다루고, C3은 다리와 부츠의 렌더링 오류를 다루므로 대상이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R3은 아이스 액스를 사용하지 않는다는 프롬프트 불일치 내용이고, C1은 존재하는 아이스 액스가 휘어지는 물리적 변형 결함이므로 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R3은 아이스 액스 부재에 관한 것이고, C2는 들고 있는 아이스 액스의 변형 현상을 다루므로 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R3은 아이스 액스 사용 여부에 관한 것이고, C3은 다리와 부츠의 그래픽 오류에 관한 것으로 서로 관련이 없습니다."
    }
  ]
}
